commands.command:
P=/home/siegfriedneto/.claude/plugins/cache/siegard-generator/siegard/5.2.0; head -c 600 specification/domain/chat-workspace/_context.log.md; echo; 
python3 -B $P/bin/spec.py --decide domain/graph-explorer/graph-pane specification <<'J'
{"field":"operations","unstated":"The survey names the graph store's actions but no domain operation names.","decided":"add-delta, replace-delta, remove-nodes, move-node, reorganize, choose-layout, settle-turn, restore-view and clear","why":"each is one action of the store the survey describes and the rules constrain, so a reader of the aggregate can find which action a rule governs"}
J
python3 -B $P/bin/spec.py --decide contracts/graph-explorer/graph-screen specification <<'J'
{"field":"answers","unstated":"Which interface texts the owner learns from, and which are only control labels.","decided":"Failure, empty, loading and outcome texts and the accessible names of regions and controls are held; headings and column labels are not","why":"policy P1 of the frontend adoption runbook keeps text that changes what the owner learns or does and leaves control labels as surface"}
J
python3 -B $P/bin/spec.py --decide domain/graph-explorer/confidence-state specification <<'J'
{"field":"values","unstated":"The survey lists five confidence states shown but the specification held no enumeration for them.","decided":"accepted, uncertain, low-confidence, disputed and superseded, spelled as the screen spells them","why":"the shown spelling uses a hyphen in low-confidence where the back end's flag uses an underscore, and the enumeration records what the screen shows"}
J
python3 -B $P/bin/spec.py specification | tail -2
